def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    last_my, last_op = history[-1]

    my_D = 0
    opp_D = 0
    dC = 0
    cC = 0
    dD = 0
    cD = 0
    my_score = 0
    op_score = 0

    for i, pair in enumerate(history):
        m, o = pair
        if m == 'D':
            my_D += 1
        if o == 'D':
            opp_D += 1

        if m == 'C' and o == 'C':
            my_score += 3
            op_score += 3
        elif m == 'C' and o == 'D':
            my_score += 0
            op_score += 5
        elif m == 'D' and o == 'C':
            my_score += 5
            op_score += 0
        else:
            my_score += 1
            op_score += 1

        if i:
            prev_my = history[i - 1][0]
            if prev_my == 'C':
                if o == 'D':
                    dC += 1
                else:
                    cC += 1
            else:
                if o == 'D':
                    dD += 1
                else:
                    cD += 1

    totalC = dC + cC
    totalD = dD + cD

    if totalC > 0:
        init_rate = float(dC) / float(totalC)
    elif opp_D > 0:
        init_rate = 0.5
    else:
        init_rate = 0.1

    if totalD > 0:
        punish_rate = float(dD) / float(totalD)
    else:
        punish_rate = 0.4

    recent = history[-12:] if n >= 12 else history
    recent_def = sum(1 for _, o in recent if o == 'D')

    recent_start = max(1, n - 12)
    recent_init = 0
    for i in range(recent_start, n):
        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            recent_init += 1

    short_start = max(1, n - 3)
    recent_init_short = 0
    for i in range(short_start, n):
        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            recent_init_short += 1

    overall_coop = 1.0 - (float(opp_D) / float(n))

    exploit = False
    if totalD > 0:
        if dD == 0 and cD >= 1 and init_rate < 0.35:
            exploit = True
        elif cD >= 3 and dD <= 1 and punish_rate < 0.35 and init_rate < 0.35:
            exploit = True

    if last_op == 'D':
        if recent_init >= 2 or init_rate > 0.6 or overall_coop < 0.25:
            return 'D'

        if n >= 2 and history[-2][0] == 'D' and recent_init_short == 0:
            if overall_coop >= 0.45:
                return 'C'

        if last_my == 'D':
            if recent_init_short == 0 and overall_coop >= 0.35:
                return 'C'
            return 'D'

        if last_my == 'C':
            if recent_init_short >= 1 or overall_coop < 0.7:
                return 'D'
            return 'D'

        return 'D'

    if exploit:
        return 'D'

    if opp_D == 0:
        if my_D > 0 and totalD == 0:
            return 'C'

        if my_D == 0:
            if n >= 65:
                return 'D'
            return 'C'

        return 'C'

    if recent_init >= 3 or init_rate > 0.55 or recent_def >= 6:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if opp_D > n // 2:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    if punish_rate > 0.7:
        return 'C'

    if punish_rate < 0.35 and cD >= 2:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    if my_score + 4 < op_score:
        if rng.random() < 0.2:
            return 'D'

    if opp_D * 5 < n and n > 80:
        if rng.random() < 0.35:
            return 'D'

    if opp_D * 4 < n and n > 50:
        if rng.random() < 0.05:
            return 'D'

    return 'C'
